PARTICLES = {'van', 'der', 'de', 'von', 'den'}
def clean_part(part):
    low = part.lower()
    if low.startswith('mc') and len(low) > 2:
        return 'Mc' + low[2:].capitalize()
    if "'" in low:
        return "'".join(seg.capitalize() for seg in low.split("'"))
    return low.capitalize()
def proper(name):
    words = []
    for i, word in enumerate(name.split()):
        subs = []
        for part in word.split('-'):
            if part.lower() in PARTICLES and i > 0:
                subs.append(part.lower())
            else:
                subs.append(clean_part(part))
        words.append('-'.join(subs))
    return ' '.join(words)
raw = "JOHN MCDONALD\nanne o'brien\nPIET VAN DER BERG\nmary-kate olsen\nJEAN-LUC PICARD\nronald mcrae\nSARAH CONNOR\nbob van dyke\nLUCY LIU\nFATIMA AL-SAYED"
names = raw.split('\n')
wrong = 0
for n in names:
    cleaned = proper(n)
    flag = ''
    if n.title() != cleaned:
        wrong += 1
        flag = '  <- naive title() gets this wrong'
    print(f'{n} -> {cleaned}{flag}')
print('names processed:', len(names))
print('names naive title-casing would mangle:', wrong)

text = '1204 Main St, Orlando, FL 32801\n88 Orange Ave, St. Louis, MO 63101\n730 Elm St, Winter Park, FL 32789\n21 St John St, Orlando, FL 32804\n15 Park Ave, St. Petersburg, FL 33701\n942 Pine St, Orlando, FL 32806\n640 St. Charles Ave, New Orleans, LA 70130\n310 Oak St, Maitland, FL 32751\n57 Cedar St, Orlando, FL 32803\n77 13th Ave, St. Cloud, FL 34769'
counts = {'expanded': 0, 'protected': 0, 'held': 0}
for line in text.split('\n'):
    street, city, rest = [p.strip() for p in line.split(',')]
    if city.startswith('St.'):
        counts['protected'] += 1
        print(f'PROTECTED (city is a Saint name): {line}')
        continue
    tokens = street.split(' ')
    if 'St.' in tokens[1:]:
        counts['held'] += 1
        print(f'HELD (St. inside street name - Saint or Street?): {line}')
        continue
    if len(tokens) > 2 and tokens[1] == 'St':
        tokens[1] = 'Saint'
    if tokens[-1] == 'St':
        tokens[-1] = 'Street'
    counts['expanded'] += 1
    print(f"EXPANDED: {line} -> {' '.join(tokens)}, {city}, {rest}")
print(counts)
